    "Codex ya revisó el hook de sesión de Eldrun y confía en él — simplemente está apagado, así que nunca se ejecuta.",
  "agents.codexHookCauseUntrusted":
    "Codex todavía no ha revisado el hook de sesión de Eldrun, así que nunca se ejecuta.",
  "agents.codexHookFallback":
    "Mientras tanto, Eldrun deduce de los propios registros de Codex qué conversación pertenece a qué pestaña. Eso funciona, pero puede confundir dos pestañas de Codex abiertas en la misma carpeta.",
  "agents.codexHookFindPre": "En la lista",
