  "pill.detachDesc1Pre": "Esto convierte",
  "pill.detachDesc1Mid": "de nuevo en un proyecto local simple: su copia de trabajo local permanece exactamente donde está y vuelve a ser el directorio del proyecto. Los archivos en el host remoto",
