  "pill.pairingWord": "emparejamiento",
  "pill.detachDesc2Post": ": el lockstep de git se detiene, y el alcance de auto-sincronización que elegiste para este host — qué carpetas cruzan, y el registro de lo que ya estaba sincronizado — se descarta. Volver a adjuntar el mismo host más tarde significa elegir ese alcance de nuevo desde cero.",
