  "pill.containerScopeRestartNote": "Cambiar esto reinicia las pestañas que cruzan el límite — un shell o script en ejecución se interrumpe. Las pestañas de agente no se ven afectadas en ningún caso.",
  "pill.containerScopeLegend": "Qué se ejecuta en el contenedor",
