  "pill.vmEgressOff": "Ninguna (totalmente cerrada)",
  "pill.vmEgressOpen": "Abierta (red completa)",
  "pill.vmEgressProxyCaveat": "La VM solo alcanza los hosts de abajo a través del proxy de Eldrun; todo lo demás se bloquea y registra. Límite honesto: un agente aún puede enviar datos a los puntos permitidos (p. ej., dentro de un prompt) — el proxy estrecha el canal, no puede cerrarlo. Los cambios de modo se aplican en el próximo arranque.",
  "pill.vmEgressOffNote": "Sin salida de red la VM no alcanza nada — las pestañas de agentes en la nube no funcionan; use un modelo local o aislamiento puro de build/test.",
