  "pill.pythonInterpMenuTitle": "El entorno Python en el que se ejecutan y depuran los scripts de este proyecto. Detectado automáticamente por defecto (venv en el árbol, poetry, conda, pyenv); fija uno cuando tu entorno esté donde Eldrun no pueda inferirlo.",
  "pill.pythonInterpreterEllipsis": "Intérprete de Python…",
  "pill.autoConnectTitleNonHeadless": "Conecta este proyecto por sí solo al iniciar y al cambiar a él. Eldrun no maneja contraseñas en este modo, así que el inicio de sesión (y la VPN, si tiene una) se abre en la terminal raíz para que te autentiques — luego el proyecto se conecta solo.",
  "pill.autoConnectTitleEligible": "Conecta este proyecto por sí solo al iniciar y al cambiar a él. Nunca pide nada: entra directamente cuando el host es accesible, y activa la VPN solo cuando no lo es.",
  "pill.autoConnectTitleNotEligible": "Guarda primero la contraseña SSH (o usa autenticación por clave) — auto-conectar solo se ofrece cuando conectar no necesita nada de ti.",
  "pill.autoConnectOnLaunch": "Conectar automáticamente al iniciar",
  "pill.persistSessionsMenuTitle": "Ejecuta la shell remota y las pestañas de Python/script de este proyecto dentro de una sesión tmux en el host, para que una ejecución larga continúe a través de una caída SSH, la suspensión del portátil o el cierre de Eldrun — la pestaña se reconecta al volver a conectar. Cerrar una pestaña sigue terminando su sesión (con confirmación). Las pestañas de agente no se ven afectadas.",
  "pill.persistentSessionsTmux": "Sesiones persistentes (tmux)",
  "pill.remoteControlMenuTitle":
    "Si las pestañas de agente Claude de este proyecto pueden supervisarse/dirigirse desde la app o el web de Claude. Haz clic para alternar: usar el ajuste global → forzar desactivado → forzar activado.",
