  "mail.encryption.offerIntro": "Cifra el correo que Eldrun guarda en este equipo, de modo que sus mensajes, adjuntos y borradores sean ilegibles sin la clave.",
  "mail.encryption.scopeHonest": "Lo que esto protege de verdad: copias de seguridad, duplicados, carpetas que sincronizas con la nube y equipos donde otras personas pueden iniciar sesión. No protege frente a quien pueda ejecutar programas como tú con Eldrun abierto, y si tu disco ya está cifrado aporta poco ante un portátil robado.",
  "mail.encryption.metadataHonest": "Sigue siendo legible en el disco: cuántos mensajes hay, qué carpetas existen y la fecha, el tamaño y el estado de leído/destacado de cada mensaje. Ocultar eso requiere cifrado de disco completo, que además oculta los nombres de archivo.",
