  "sysmon.userCountMany": "{count} usuarios",
  "sysmon.youChip": "tú",
  "sysmon.youChipTitle": "La cuenta con la que Eldrun está conectado",
  "sysmon.collapseByUser": "Contraer uso por usuario",
